78	
79		// 调用方为页面展示肆意修改拿到的记录：基本字段、测量、逐项判定全改
80		m := list[0]
81		m.ID = "HACK"
82		m.PointID = "P9"
83		m.SampledAt = at(1, 0)
84		m.Status = StatusVoided
85		m.Exceeded = false
86		m.VoidReason = "伪造原因"
87		m.Measurements[0].Item = "SS"
88		m.Measurements[0].Value = 0.1
89		m.Measurements[1].Value = 999
90		m.Results[0].Item = "SS"
91		m.Results[0].Value = 0.1
92		m.Results[0].Limit = 1000
93		m.Results[0].LimitEffective = at(20, 0)
94		m.Results[0].Exceeded = false
95		m.Results[1].Limit = 0.01
96		m.Results[1].Exceeded = true
97	
98		// 再次查询：保存记录必须仍是原内容
99		list2, err := s.ListByPoint("P1")
100		if err != nil || len(list2) != 1 {
101			t.Fatalf("ListByPoint after mutation: %+v err=%v", list2, err)
102		}
103		checkTwoItemSaved(t, list2[0], "修改后再次查询")
104		// 重复确认：仍返回已保存结论，不能采纳调用方临时编辑的结果
105		again, err := s.Confirm("S1")
106		if err != nil {
107			t.Fatalf("重复确认: %v", err)
108		}
109		checkTwoItemSaved(t, again, "修改后重复确认")
110		// 最近有效结果也不受影响
111		latest2, ok, err := s.LatestResult("P1")
112		if err != nil || !ok {
113			t.Fatalf("修改后最近有效结果: %+v ok=%v err=%v", latest2, ok, err)
114		}
115		checkTwoItemSaved(t, latest2, "修改后最近有效结果")
116		// 修改前取得的 latest 副本保持取得时的内容
117		checkTwoItemSaved(t, latest, "先前取得的最近有效结果")
118	}
119	
120	// 列表记录与最近有效结果分别取得时互不影响：改其中一份，另一份保持原样；
121	// 改掉本地记录的编号、采样点、采样时间或状态，不能改变保存记录的归属、
122	// 排列位置和是否属于最近有效结果；两个项目的原始测量与判定依据都保持完整，
123	// 不允许只保住整份超标标记而某个项目被替换。
124	func TestListAndLatestRecordsAreIndependent(t *testing.T) {
125		s, _ := open(t)
126		mustPoint(t, s, "P1", "取水口")
127		mustPoint(t, s, "P2", "排水口")
128		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
129		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
130		mustLimit(t, s, "P2", "pH", 8.0, at(1, 0))
131	
132		// S0 较早、S1 较晚且为双项目样品；P2 的 SX 用来检查归属不被改写
133		mustSample(t, s, "S0", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
134		mustSample(t, s, "S1", "P1", at(10, 0),
135			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
136		mustSample(t, s, "SX", "P2", at(20, 0), Measurement{Item: "pH", Value: 7})
137		if _, err := s.Confirm("S0"); err != nil {
138			t.Fatalf("Confirm S0: %v", err)
139		}
140		if _, err := s.Confirm("S1"); err != nil {
141			t.Fatalf("Confirm S1: %v", err)
142		}
143	
144		list, err := s.ListByPoint("P1")
145		if err != nil || len(list) != 2 {
146			t.Fatalf("ListByPoint: %+v err=%v", list, err)
147		}
148		if list[0].ID != "S1" || list[1].ID != "S0" {
149			t.Fatalf("排列应为 S1 在前 S0 在后: %+v", list)
150		}
151		latest, ok, err := s.LatestResult("P1")
152		if err != nil || !ok || latest.ID != "S1" {
153			t.Fatalf("最近有效结果应为 S1: %+v ok=%v err=%v", latest, ok, err)
154		}
155	
156		// 改最近有效结果这份记录：换掉其中一个项目的判定、伪造归属与状态
157		latest.ID = "S0"
158		latest.PointID = "P2"
159		latest.SampledAt = at(1, 0)
160		latest.Status = StatusVoided
161		latest.Exceeded = false
162		latest.Results[1] = ItemResult{Item: "SS", Value: 1, Limit: 2, LimitEffective: at(2, 0), Exceeded: false}
163		latest.Measurements = append(latest.Measurements, Measurement{Item: "SS", Value: 1})
164	
165		// 列表里先取得的那份记录不受 latest 副本修改的影响
166		checkTwoItemSaved(t, list[0], "修改 latest 后列表中的记录")
167	
168		// 再改列表记录：编号、采样点、采样时间、状态全部伪造
169		list[0].ID = "ZZZ"
170		list[0].PointID = "P2"
171		list[0].SampledAt = time.Time{}
172		list[0].Status = StatusPending
173		list[0].Results[0].Exceeded = false
174	
175		// 保存记录的归属、排列位置、最近有效结果身份不变
176		list2, err := s.ListByPoint("P1")
177		if err != nil || len(list2) != 2 {
178			t.Fatalf("修改后 ListByPoint: %+v err=%v", list2, err)
179		}
180		if list2[0].ID != "S1" || list2[1].ID != "S0" {
181			t.Fatalf("修改本地记录不应改变排列位置: %+v", list2)
182		}
183		checkTwoItemSaved(t, list2[0], "修改列表记录后再次查询")
184		// 两个项目各自的原始测量与判定依据都完整，COD 一项不能被替换掉
185		if list2[0].Results[0].Item == "SS" || list2[0].Results[1].Item == "SS" {
186			t.Fatalf("某个项目被替换: %+v", list2[0].Results)
187		}
188		latest2, ok, err := s.LatestResult("P1")
189		if err != nil || !ok || latest2.ID != "S1" {
190			t.Fatalf("修改本地记录不应改变最近有效结果: %+v ok=%v err=%v", latest2, ok, err)
191		}
192		checkTwoItemSaved(t, latest2, "修改后最近有效结果")
193		// P2 的归属不被伪造的 PointID 改变
194		listP2, err := s.ListByPoint("P2")
195		if err != nil || len(listP2) != 1 || listP2[0].ID != "SX" {
196			t.Fatalf("P2 的样品归属被改动: %+v err=%v", listP2, err)
197		}
198	}
199	
200	// 已确认样品经正常作废后，按点查询保留原测量、原判定结果和作废原因。
201	// 调用方把查询得到的作废记录改回已确认、清空作废原因，不能使保存记录
202	// 恢复有效：再次确认仍拒绝，最近有效结果继续排除它，没有其他有效结果时
203	// 明确无结果。作废前取得的已确认记录保持取得时的内容。
204	func TestVoidedRecordMutationDoesNotRevive(t *testing.T) {
205		s, _ := open(t)
206		mustPoint(t, s, "P1", "取水口")
207		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
208		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
209		mustSample(t, s, "S1", "P1", at(10, 0),
210			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
211		before, err := s.Confirm("S1")
212		if err != nil {
213			t.Fatalf("Confirm: %v", err)
214		}
215		checkTwoItemSaved(t, before, "作废前确认")
216	
217		if _, err := s.Void("S1", "采样瓶破损"); err != nil {
218			t.Fatalf("Void: %v", err)
219		}
220	
221		checkVoided := func(smp Sample, label string) {
222			t.Helper()
223			if smp.Status != StatusVoided || smp.VoidReason != "采样瓶破损" {
224				t.Fatalf("%s: 作废状态或原因被改动: %+v", label, smp)
225			}
226			// 原测量与原判定结果（含逐项依据和整份超标标记）保留
227			if smp.ID != "S1" || smp.PointID != "P1" || !smp.SampledAt.Equal(at(10, 0)) {
228				t.Fatalf("%s: 基本字段被改动: %+v", label, smp)
229			}
230			if !smp.Exceeded || len(smp.Measurements) != 2 || len(smp.Results) != 2 {
231				t.Fatalf("%s: 原判定结果未保留: %+v", label, smp)
232			}
233			rs := map[string]ItemResult{}
234			for _, r := range smp.Results {
235				rs[r.Item] = r
236			}
237			if ph := rs["pH"]; ph.Value != 9 || ph.Limit != 8.0 || !ph.Exceeded {
238				t.Fatalf("%s: pH 原判定未保留: %+v", label, ph)
239			}
240			if cod := rs["COD"]; cod.Value != 30 || cod.Limit != 30.0 || cod.Exceeded {
241				t.Fatalf("%s: COD 原判定未保留: %+v", label, cod)
242			}
243		}
244	
245		list, err := s.ListByPoint("P1")
246		if err != nil || len(list) != 1 {
247			t.Fatalf("ListByPoint: %+v err=%v", list, err)
248		}
249		checkVoided(list[0], "作废后按点查询")
250	
251		// 作废前取得的已确认记录保持取得时的内容，不随作废操作变化
252		checkTwoItemSaved(t, before, "作废后先前取得的记录")
253	
254		// 调用方把查询得到的作废记录改回已确认、清空作废原因、伪造结论
255		forged := list[0]
256		forged.Status = StatusConfirmed
257		forged.VoidReason = ""
258		forged.Exceeded = false
259		forged.Results[0].Exceeded = false
260	
261		// 保存记录不能恢复有效：再次确认仍拒绝
262		if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
263			t.Fatalf("已作废样品再次确认应拒绝, got %v", err)
264		}
265		// 最近有效结果继续排除该样品；没有其他有效结果时明确无结果
266		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
267			t.Fatalf("作废后应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
268		}
269		// 再次查询仍是作废记录，原测量、原判定与作废原因俱在
270		list2, err := s.ListByPoint("P1")
271		if err != nil || len(list2) != 1 {
272			t.Fatalf("伪造后 ListByPoint: %+v err=%v", list2, err)
273		}
274		checkVoided(list2[0], "伪造后再次查询")
275		// 正常重复作废（相同原因）仍返回保存的作废记录
276		again, err := s.Void("S1", "采样瓶破损")
277		if err != nil {
278			t.Fatalf("重复作废: %v", err)
279		}
280		checkVoided(again, "重复作废返回值")
281	}
