79	// 返回内容必须整体属于 S0（pH 7、COD 20，两项与整份均达标），
80	// 不能混入作废记录 S1 的 pH 9、超标依据或任何字段。
81	func checkEarlierS0(t *testing.T, smp Sample, label string) {
